// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    receive() external payable {}
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 balance, uint256 amount) public {
        balance = bound(balance, 1, 1 ether);
        vm.deal(address(c), balance);
        amount = bound(amount, 0, address(c).balance);
        uint256 before = address(c).balance;
        vm.prank(address(this));
        c.withdraw(amount);
        assertTrue(address(c).balance == before - amount);
    }
}
